import org.junit.Assert.*
import org.junit.Test
import org.junit.runner.RunWith
import java.io.File

@RunWith(AndroidJUnit4::class)
class ScanPerspectiveTest {
    @Test fun skewedPageIsRectangularAndInputRemainsUnchanged() {
        val source = Bitmap.createBitmap(400,400,Bitmap.Config.ARGB_8888)
        source.eraseColor(Color.BLACK)
        val q = listOf(.2,.1,.85,.2,.8,.9,.1,.8)
        val path = Path().apply { moveTo(80f,40f);lineTo(340f,80f);lineTo(320f,360f);lineTo(40f,320f);close() }
        Canvas(source).drawPath(path, Paint().apply { color=Color.WHITE })
        val before = IntArray(160000);source.getPixels(before,0,400,0,0,400,400)
        val output = ScanPerspective.warp(source,q)
        try {
            assertTrue(output.width in 260..290);assertTrue(output.height in 280..300)
            // All four interior quadrants are document pixels, not the black table.
            for(x in listOf(.1,.9)) for(y in listOf(.1,.9)) {
                assertEquals(Color.WHITE,output.getPixel((x*output.width).toInt(),(y*output.height).toInt()))
            }
            val after=IntArray(160000);source.getPixels(after,0,400,0,0,400,400)
            assertArrayEquals(before,after)
        } finally { output.recycle();source.recycle() }
    }
    @Test fun crossedDegenerateAndNonFiniteCornersAreRejected() {
        for(q in listOf(listOf(.1,.1,.9,.9,.9,.1,.1,.9), List(8){.5}, listOf(Double.NaN,.1,.9,.1,.9,.9,.1,.9))) {
            try { ScanPerspective.validate(q);fail("Invalid quad accepted") } catch(_: IllegalArgumentException) {}
        }
    }
    @Test fun perspectiveDraftSurvivesRestartAndUndoRestoresOriginalGeometry() {
        val context=InstrumentationRegistry.getInstrumentation().targetContext
        val store=ScanDraftStore(context);store.clear()
        val input=File.createTempFile("quad_", ".png",context.cacheDir)
        val bitmap=Bitmap.createBitmap(400,500,Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.BLUE)
        input.outputStream().use { bitmap.compress(Bitmap.CompressFormat.PNG,100,it) };bitmap.recycle()
        try {
            val page=store.add(listOf(input.path))[0]
            val raw=File(store.originalInfo(page).getValue("path"));val before=raw.readBytes()
            val edited=store.edit(listOf(page),"gray",null,listOf(.2,.1,.9,.2,.8,.9,.1,.8))[0]
            val recreated=ScanDraftStore(context);assertEquals(listOf(edited),recreated.recover())
            val undone=recreated.undo(edited)[0]
            val image=BitmapFactory.decodeFile(undone)
            try { assertEquals(400,image.width);assertEquals(500,image.height);assertTrue(Color.blue(image.getPixel(20,20))>220) }
            finally { image.recycle() }
            assertArrayEquals(before,raw.readBytes())
        } finally { input.delete();store.clear() }
    }
    @Test fun exportRebuildsFromOriginalAndNeverClearsDraft() {
        val context=InstrumentationRegistry.getInstrumentation().targetContext
        val store=ScanDraftStore(context);store.clear()
        val input=File.createTempFile("export_original_", ".png",context.cacheDir)
        val bitmap=Bitmap.createBitmap(2400,2400,Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.BLUE)
        input.outputStream().use { bitmap.compress(Bitmap.CompressFormat.PNG,100,it) };bitmap.recycle()
        val outputs=mutableListOf<File>()
        try {
            val pages=store.add(listOf(input.path))
            val raw=File(store.originalInfo(pages[0]).getValue("path"));val bytes=raw.readBytes()
            for(high in listOf(false,true)) {
                val pdf=File(store.exportPdf(pages,high));outputs.add(pdf)
                com.tom_roush.pdfbox.pdmodel.PDDocument.load(pdf).use { doc ->
                    assertEquals(1,doc.numberOfPages)
                    val resources=doc.getPage(0).resources
                    val image=resources.getXObject(resources.xObjectNames.first()) as com.tom_roush.pdfbox.pdmodel.graphics.image.PDImageXObject
                    assertEquals(if(high) 2400 else 1200,image.width)
                }
                assertEquals(pages,ScanDraftStore(context).recover())
                assertArrayEquals(bytes,raw.readBytes())
            }
            try { store.exportPdf(listOf("/missing.jpg"),true);fail("Invalid draft accepted") }
            catch(_:IllegalArgumentException) {}
            assertEquals(pages,store.pages())
        } finally { outputs.forEach{it.delete()};input.delete();store.clear() }
    }

    @Test fun savedArchiveRestoresOriginalEditsAndProtectsExistingDraft() {
        val context=InstrumentationRegistry.getInstrumentation().targetContext
        val store=ScanDraftStore(context);store.clear()
        val id="archive_test_"+System.nanoTime()
        val input=File.createTempFile("archive_source_", ".png",context.cacheDir)
        val bitmap=Bitmap.createBitmap(400,500,Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.BLUE)
        input.outputStream().use { bitmap.compress(Bitmap.CompressFormat.PNG,100,it) };bitmap.recycle()
        try {
            val bytes=input.readBytes()
            val first=store.add(listOf(input.path))[0]
            store.edit(listOf(first),"gray",listOf(.1,.1,.9,.9))
            assertTrue(store.archive(id))
            try { store.openArchive(id);fail("Existing draft overwritten") } catch(_:IllegalArgumentException) {}
            store.clear()
            val recreated=ScanDraftStore(context)
            val restored=recreated.openArchive(id)[0]
            val image=BitmapFactory.decodeFile(restored)
            try { assertEquals(320,image.width);assertEquals(400,image.height) } finally { image.recycle() }
            assertArrayEquals(bytes,File(recreated.originalInfo(restored).getValue("path")).readBytes())
            val undone=recreated.undo(restored)[0]
            val original=BitmapFactory.decodeFile(undone)
            try { assertEquals(400,original.width);assertTrue(Color.blue(original.getPixel(20,20))>220) } finally { original.recycle() }
            recreated.clear();assertTrue(recreated.deleteArchive(id))
            try { recreated.openArchive(id);fail("Deleted archive restored") } catch(_:IllegalArgumentException) {}
        } finally { input.delete();store.clear();store.deleteArchive(id) }
    }


    @Test fun tonalEditsPersistAndUndoWithoutChangingOriginalBytes() {
        val context=InstrumentationRegistry.getInstrumentation().targetContext
        val store=ScanDraftStore(context);store.clear()
        val input=File.createTempFile("tone_source_", ".png", context.cacheDir)
        val bitmap=Bitmap.createBitmap(120,160,Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.rgb(90,90,90))
        input.outputStream().use { bitmap.compress(Bitmap.CompressFormat.PNG,100,it) };bitmap.recycle()
        val id="tone_archive_"+System.nanoTime()
        try {
            val first=store.add(listOf(input.path))[0]
            val edited=store.edit(listOf(first),"enhance",null,brightness=.4,contrast=1.2)[0]
            val image=BitmapFactory.decodeFile(edited)
            try { assertTrue(Color.red(image.getPixel(60,60))>100) } finally { image.recycle() }
            assertTrue(store.archive(id));store.clear()
            val restored=store.openArchive(id)[0]
            val state=store.editPreview(restored)
            assertEquals("enhance",state["filter"]);assertEquals(.4,state["brightness"]);assertEquals(1.2,state["contrast"])
            assertArrayEquals(input.readBytes(),File(store.originalInfo(restored).getValue("path")).readBytes())
            val undone=store.undo(restored)[0]
            val original=BitmapFactory.decodeFile(undone)
            try { assertTrue(Color.red(original.getPixel(60,60)) in 87..93) } finally { original.recycle() }
            try { store.edit(listOf(undone),"original",null,brightness=Double.NaN);fail("NaN accepted") } catch(_:IllegalArgumentException) {}
            assertEquals(listOf(undone),store.pages())
        } finally { input.delete();store.clear();store.deleteArchive(id) }
    }
    @Test fun exportPaperOrientationAndMarginsProduceReadablePageBounds() {
        val context=InstrumentationRegistry.getInstrumentation().targetContext
        val store=ScanDraftStore(context);store.clear()
        val input=File.createTempFile("paper_source_", ".png", context.cacheDir)
        val bitmap=Bitmap.createBitmap(120,160,Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.BLUE)
        input.outputStream().use { bitmap.compress(Bitmap.CompressFormat.PNG,100,it) };bitmap.recycle()
        val outputs=mutableListOf<File>()
        try {
            val pages=store.add(listOf(input.path))
            for(paper in listOf("a4","letter","legal")) for(orientation in listOf("portrait","landscape")) {
                val pdf=File(store.exportPdf(pages,false,paper,orientation,0));outputs.add(pdf)
                com.tom_roush.pdfbox.pdmodel.PDDocument.load(pdf).use { doc ->
                    val box=doc.getPage(0).mediaBox
                    val expected=when(paper) { "letter" -> 792f; "legal" -> 1008f; else -> 841.8898f }
                    assertEquals(expected, maxOf(box.width,box.height), .1f)
                    assertEquals(orientation=="landscape",box.width>box.height)
                    assertEquals(1,doc.numberOfPages)
                }
            }
            try { store.exportPdf(pages,false,"invalid");fail("Unknown paper accepted") } catch(_:IllegalArgumentException) {}
            assertEquals(pages,store.pages())
        } finally { outputs.forEach { it.delete() };input.delete();store.clear() }
    }

    @Test fun removedBatchSurvivesRestartAndRestoresOrderAndEdits() {
        val context=InstrumentationRegistry.getInstrumentation().targetContext
        val store=ScanDraftStore(context);store.clear()
        val input=File.createTempFile("removed_source_", ".png",context.cacheDir)
        val image=Bitmap.createBitmap(80,100,Bitmap.Config.ARGB_8888);image.eraseColor(Color.BLUE)
        input.outputStream().use { image.compress(Bitmap.CompressFormat.PNG,100,it) };image.recycle()
        try {
            val pages=store.add(listOf(input.path,input.path,input.path))
            val edited=store.edit(listOf(pages[1]),"gray",null)
            store.replace(listOf(edited[1]))
            assertEquals(edited, ScanDraftStore(context).undoRemoval())
            val rotated=store.rotate(edited[1])
            store.replace(emptyList())
            assertEquals(rotated,ScanDraftStore(context).undoRemoval())
            assertEquals(rotated,store.undoRemoval())
            store.replace(listOf(rotated[0]));store.clear()
            assertTrue(store.undoRemoval().isEmpty())
        } finally { input.delete();store.clear() }
    }
