  testWidgets(
    'failed PDF save never clears the captured draft',
    (tester) async {
      var cleared = false;
      messenger.setMockMethodCallHandler(camera, (call) async {
        if (call.method == 'clear') cleared = true;
        return ['/tmp/page.jpg'];
      });
