      final canvas = Canvas(recorder);
      canvas.drawRect(const Rect.fromLTWH(0,0,600,800), Paint()..color = const Color(0xfff6f3e9));
      void line(String text, double y, double size) {
        final p = TextPainter(text: TextSpan(text: text, style: TextStyle(color: Colors.black87, fontSize: size, fontFamily: 'Manrope')), textDirection: TextDirection.ltr)..layout(maxWidth: 520);
        p.paint(canvas, Offset(40,y));
      }
      line('PHARM D / STUDY NOTES', 50, 28);
      line('Sample document for editor QA', 110, 22);
      for(var i=0;i<8;i++) {
        line('Section ${i+1} — revision notes', 180.0 + i*65, 20);
        canvas.drawLine(Offset(40,220.0+i*65), Offset(560,220.0+i*65), Paint()..color = Colors.blueGrey..strokeWidth = 1);
      }
      final picture = recorder.endRecording();
      final image = await picture.toImage(600,800);
      final data = await image.toByteData(format: ui.ImageByteFormat.png);
      image.dispose();picture.dispose();return data!.buffer.asUint8List();
    });
    messenger.setMockMethodCallHandler(channel, (_) async => {
      'bytes': bytes,
      'filter': 'enhance', 'brightness': .25, 'contrast': 1.2,
    });
    addTearDown(() => messenger.setMockMethodCallHandler(channel, null));
    ScanPageEdit? result;
    await tester.pumpWidget(MaterialApp(debugShowCheckedModeBanner: false, theme: AppTheme.light(), home: Builder(builder: (context) => Scaffold(body: TextButton(
      onPressed: () async { result = await Navigator.of(context).push<ScanPageEdit>(MaterialPageRoute(builder: (_) => const ScanPageEditor(path: '/draft/page.jpg', nativeDraft: true))); },
      child: const Text('Edit'),
    )))));
    await tester.runAsync(() async {
      await tester.tap(find.text('Edit'));
      await tester.pump();
      for (var i = 0; i < 100; i++) {
        await Future<void>.delayed(const Duration(milliseconds: 10));
        await tester.pump();
        if (find.byType(CircularProgressIndicator).evaluate().isEmpty) break;
      }
    });
    await tester.pumpAndSettle();
    await tester.tap(find.text('Adjust'));
    await tester.pumpAndSettle();
    expect(find.byType(Slider), findsNWidgets(2));
    if (const bool.fromEnvironment('HYZEN_CAPTURE_QA')) {
      await expectLater(find.byType(MaterialApp), matchesGoldenFile('../qa/scan_editor_tone.png'));
    }
    await tester.tap(find.text('4-corner crop'));
    await tester.pumpAndSettle();
    final gesture = await tester.startGesture(tester.getCenter(find.byKey(const ValueKey('crop-corner-0'))));
    await gesture.moveBy(const Offset(25, 15));
    await tester.pump();
    if (const bool.fromEnvironment('HYZEN_CAPTURE_QA')) {
      await expectLater(find.byType(MaterialApp), matchesGoldenFile('../qa/scan_editor_crop_loupe.png'));
    }
    await gesture.up();
    await tester.pump();
    await tester.runAsync(() async {
      await tester.tap(find.text('Apply'));
      await tester.pump();
      await Future<void>.delayed(const Duration(milliseconds: 20));
    });
    await tester.pumpAndSettle();
    expect(result?.filter, 'enhance');
    expect(result?.brightness, .25);
    expect(result?.contrast, 1.2);
    expect(result?.crop, hasLength(8));
    expect(result!.crop![0], greaterThan(.03));
    expect(result!.crop![2], .97);
    expect(result!.crop![3], .03);
    expect(tester.takeException(), isNull);
  });
}

